internal static class TestLatency03Output {
 const long F=10000000,E=100000000;static int checks;
 static void Need(bool yes,string message){checks++;if(!yes)throw new Exception(message);}
 static PreparedTransientBus Bank(){var bus=new PreparedTransientBus(1,2,.95);for(int i=0;i<8;i++){var pcm=new float[2048];pcm[960]=.001f;pcm[961]=-.001f;pcm[1920]=.0001f;pcm[1921]=.0001f;bus.Register(i,new PreparedTransientKernel(pcm,1024,480,960,i+1,1,1,1,1,480));}return bus;}
 static PreparedTransientEvent Event(int id,long occurrence){return new PreparedTransientEvent{EventId=id,SourceSequence=id-1,SourceId=1,SourceGeneration=1,KernelSlot=0,KernelGeneration=1,SceneGeneration=1,ListenerGeneration=1,Priority=0,OccurrenceLowerQpc=occurrence,OccurrenceUpperQpc=occurrence,AcquisitionBeforeQpc=occurrence,ObservationAfterQpc=occurrence,Frequency=F,MaximumLatenessFrames=2400,SessionLow=1,SessionHigh=2};}
 static Latency03ClockSample Sample(long milliseconds,ulong position,int hr=0){long q=E+milliseconds*F/1000;return new Latency03ClockSample{BeforeQpc=q,AfterQpc=q+10,RawQpc100ns=q,DevicePosition=position,SubmittedFrames=20000,HResult=hr};}
 static Latency03PresentationClock Clock(){var clock=new Latency03PresentationClock(48000,F,E);var a=Sample(10,480);var b=Sample(20,960);Need(clock.Observe(ref a)==0&&!clock.IsReady,"one arrived positive sample cannot qualify clock");Need(clock.Observe(ref b)==1&&clock.IsReady,"two arrived advancing samples qualify interpolation");return clock;}
 sealed class FakeRender:IAudioRenderClient,IDisposable {internal readonly float[] Samples=new float[32768];internal long Written;internal int Releases,Acquires,AcquireResult=0,ReleaseResult;readonly IntPtr buffer=Marshal.AllocHGlobal(2048*8);uint requested;
  public int GetBuffer(uint frames,out IntPtr data){Acquires++;requested=frames;data=AcquireResult==0?buffer:IntPtr.Zero;return AcquireResult;}
  public unsafe int ReleaseBuffer(uint frames,uint flags){Releases++;if(ReleaseResult!=0)return ReleaseResult;if(frames!=requested)return -1;var p=(float*)buffer;for(int i=0;i<frames*2;i++)Samples[Written*2+i]=p[i];Written+=frames;return 0;}
  public void Dispose(){Marshal.FreeHGlobal(buffer);}
 }
 class FakeLegacy:IAudioClient {internal int LegacyCalls,NewCalls,QueryCalls;internal long Duration;internal uint Flags;
  public int Initialize(int mode,uint flags,long duration,long periodicity,IntPtr format,IntPtr session){LegacyCalls++;Flags=flags;Duration=duration;return 0;}
  public int GetBufferSize(out uint n){n=1056;return 0;}public int GetStreamLatency(out long d){d=200000;return 0;}public int GetCurrentPadding(out uint n){n=0;return 0;}public int IsFormatSupported(int s,IntPtr f,out IntPtr p){p=IntPtr.Zero;return 0;}public int GetMixFormat(out IntPtr p){p=IntPtr.Zero;return 0;}public int GetDevicePeriod(out long d,out long m){d=100000;m=10000;return 0;}public int Start(){return 0;}public int Stop(){return 0;}public int Reset(){return 0;}public int SetEventHandle(IntPtr h){return 0;}public int GetService(ref Guid i,out object s){s=null;return 0;}
 }
 sealed class FakeExtended:FakeLegacy,IAudioClient3Latency03 {internal int QueryResult;internal uint Selected;
  public int IsOffloadCapable(int c,out bool b){b=false;return 0;}public int SetClientProperties(IntPtr p){throw new Exception("Client properties must not be changed");}public int GetBufferSizeLimits(IntPtr p,bool b,out long min,out long max){min=0;max=0;return 0;}
  public int GetSharedModeEnginePeriod(IntPtr p,out uint d,out uint f,out uint min,out uint max){QueryCalls++;d=512;f=64;min=63;max=1025;return QueryResult;}
  public int GetCurrentSharedModeEnginePeriod(out IntPtr p,out uint n){n=512;var format=WaveFormat.FloatStereo48k();p=Marshal.AllocCoTaskMem(Marshal.SizeOf(typeof(WaveFormat)));Marshal.StructureToPtr(format,p,false);return 0;}
  public int InitializeSharedAudioStream(uint flags,uint period,IntPtr f,IntPtr s){NewCalls++;Flags=flags;Selected=period;return 0;}
 }
 static void Throws(Action run,string why){bool threw=false;try{run();}catch(ArgumentException){threw=true;}catch(InvalidOperationException){threw=true;}catch(NotSupportedException){threw=true;}Need(threw,why);}
 static void ClockTests(){var c=Clock();long mapped;Need(c.MapLatest(E+F*15/1000,0,out mapped)==1&&mapped==723,"interpolate arrived stream position with actual query/quantization guard");Need(c.MapLatest(E+F*21/1000,0,out mapped)==0,"future-to-clock event waits instead of forecasting");Need(c.MapLatest(E+F*5/1000,0,out mapped)<0,"unobserved historical position rejected");Need(c.MapLatest(Int64.MaxValue,0,out mapped)<0,"unrepresentable counter rejected without arithmetic overflow");
  var d=Clock();var bad=Sample(30,1440,1);Need(d.Observe(ref bad)<0&&!d.IsReady,"S_FALSE terminal; no retry hides clock uncertainty");d=Clock();bad=Sample(30,479);Need(d.Observe(ref bad)<0,"backward stream position terminal");d=Clock();bad=Sample(30,1900);Need(d.Observe(ref bad)<0,"device/QPC pair discrepancy rejected");d=Clock();bad=Sample(30,1440);bad.AfterQpc=bad.BeforeQpc+F/100;Need(d.Observe(ref bad)<0,"long clock call rejected");d=Clock();bad=Sample(200,960);Need(d.Observe(ref bad)<0,"frozen observed clock terminates after bounded age");
  var other=new Latency03PresentationClock(96000,13000000,E);long q0=E+130000,q1=E+260000;var a=new Latency03ClockSample{BeforeQpc=q0,AfterQpc=q0+13,RawQpc100ns=q0/13*10+(q0%13)*10/13,DevicePosition=960,SubmittedFrames=2000};var b=new Latency03ClockSample{BeforeQpc=q1,AfterQpc=q1+13,RawQpc100ns=q1/13*10+(q1%13)*10/13,DevicePosition=1920,SubmittedFrames=2000};Need(other.Observe(ref a)==0&&other.Observe(ref b)==1,"device position units and raw QPC100ns independently converted");Need(other.MapLatest(E+195000,0,out mapped)==1&&mapped>=720&&mapped<=723,"non-10MHz counter never treated as100ns ticks");
 }
 static unsafe void PendingTests(){var clock=Clock();var bus=Bank();bus.SealClock(clock);var ev=Event(1,E+F*25/1000);Need(bus.TryAdmit(ev,ev.ObservationAfterQpc),"qualified identity queued before next clock bracket");var pcm=new float[1920];fixed(float* p=pcm)Need(bus.Mix(p,960,0,1),"bounded first mix can defer clock mapping");Need(bus.Queued==1&&bus.Receipt(1).FirstOutputFrame<0,"no event emitted into an unobserved clock interval");bus.CommitSubmission(E+F*26/1000,E+F*26/1000+10);var sample=Sample(30,1440);Need(clock.Observe(ref sample)==1,"next arrived anchor");Array.Clear(pcm,0,pcm.Length);fixed(float* p=pcm)Need(bus.Mix(p,960,960,1),"next mix qualifies waiting event");var r=bus.Receipt(1);Need(bus.Queued==0&&r.IdealEmissionFrame==1203&&r.FirstOutputFrame==1683&&r.ClockQualifiedQpc==sample.AfterQpc,"original event time maps once; propagation retained");Need(r.FirstWritableFrameAtConsumer==960&&r.MappingUncertaintyFrames==3,"consumer first-writable frame and mapping guard retained");Need(bus.FinishCancellation(100),"pending path completes independent cancellation");
  bus=Bank();bus.SealClock(Clock());for(int i=1;i<=128;i++){ev=Event(i,E+F*25/1000);ev.SourceId=(i-1)%8+1;ev.KernelSlot=ev.SourceId-1;ev.Priority=i<=64?0:1;Need(bus.TryAdmit(ev,ev.ObservationAfterQpc),"bounded128 pending descriptors");}fixed(float* p=pcm)bus.Mix(p,960,0,1);Need(bus.Queued==128&&bus.PeakClockPending==128,"pending descriptors share global128budget with lanes");ev=Event(129,E+F*25/1000);Need(!bus.TryAdmit(ev,ev.ObservationAfterQpc),"pending storage cannot hide another128descriptor admission");Need(bus.FinishCancellation(100)&&bus.Queued==0,"all pending descriptors retired and drained");
 }
 static void FillRing(PcmRing ring,float value){var a=new float[1024];for(int i=0;i<a.Length;i++)a[i]=value;for(int i=0;i<8;i++)Need(ring.TryWrite(a,512),"prefill original continuous ring");}
 static unsafe void SubmissionTests(){var bus=Bank();var session=new Latency03OutputSession(bus,"authored-endpoint-not-opened",0,35,1);session.EndpointBufferFrames=1056;bus.Seal(new SyntheticPresentationClock(E,F,0));var ring=new PcmRing();FillRing(ring,.05f);Need(bus.TryAdmit(Event(1,E),E),"authored impulse admitted");using(var sink=new FakeRender()){Need(session.Submit(ring,sink,1056,0,0,1),"fake ReleaseBuffer route");var r=bus.Receipt(1);Need(sink.Releases==1&&r.Status==3&&r.FirstOutputFrame==480&&r.SubmissionAfterQpc>=r.SubmissionBeforeQpc,"only successful fake ReleaseBuffer acknowledges first onset");Need(sink.Samples[960]==.051f&&sink.Samples[0]==.05f,"continuous PCM plus original impulse without bank/gain changes");session.MarkJoined();var row=session.CopySubmissionSamples()[0];Need(row.AcquireBeforeQpc<=row.AcquireAfterQpc&&row.FillBeforeQpc<=row.FillAfterQpc&&row.ReleaseBeforeQpc<=row.ReleaseAfterQpc,"acquire/mix/release brackets separate");Need(row.ReleaseBeforeQpc==r.SubmissionBeforeQpc,"event submission begins at ReleaseBuffer, not Fill");Need(session.CompleteAfterIngressAndOutputJoin()&&session.CleanupComplete,"control-thread cleanup completion separate from stop request");}
  bus=Bank();session=new Latency03OutputSession(bus,"authored",0,35,1);session.EndpointBufferFrames=1056;bus.Seal(new SyntheticPresentationClock(E,F,0));ring=new PcmRing();FillRing(ring,.05f);Need(bus.TryAdmit(Event(1,E),E),"release-fault fixture admitted");using(var sink=new FakeRender()){sink.ReleaseResult=unchecked((int)0x80004005);Need(!session.Submit(ring,sink,1056,0,0,1)&&session.Failure==Latency03Failure.BufferRelease,"release failure terminal with no retry");Need(bus.Receipt(1).SubmissionAfterQpc==0&&bus.Receipt(1).Status==2,"mixed data not claimed submitted after failed ReleaseBuffer");}
  bus=Bank();session=new Latency03OutputSession(bus,"authored",0,35,1);session.EndpointBufferFrames=1056;bus.Seal(new SyntheticPresentationClock(E,F,0));ring=new PcmRing();using(var sink=new FakeRender()){Need(!session.Submit(ring,sink,1056,0,0,1)&&session.Failure==Latency03Failure.ContinuousUnderflow&&ring.UnderflowFrames==1056,"continuous starvation cannot be hidden by event bus");}
  var first=new PcmRing();var second=new PcmRing();FillRing(first,.1f);FillRing(second,.1f);bus=Bank();session=new Latency03OutputSession(bus,"authored",0,35,1);session.EndpointBufferFrames=2048;bus.Seal(new SyntheticPresentationClock(E,F,0));var original=new float[4096];long frame=0;using(var sink=new FakeRender()){foreach(int frames in new[]{1056,480,512,767}){fixed(float* p=original)first.FillCalibrated(p,frames,1);Need(session.Submit(second,sink,(uint)frames,frame,0,1),"empty experimental bus uses unchanged continuous fill");for(int i=0;i<frames*2;i++)Need(original[i]==sink.Samples[frame*2+i],"every continuous sample bit-exact");Need(first.TakeCredits()==second.TakeCredits()&&first.BufferedFrames==second.BufferedFrames,"ring credits and residence capacity unchanged");frame+=frames;}}
 }
 static void InitializeTests(){var legacy=new FakeLegacy();var session=new Latency03OutputSession(Bank(),"authored",0,35,1);session.Initialize(legacy,IntPtr.Zero);Need(legacy.LegacyCalls==1&&legacy.Duration==200000&&legacy.Flags==0x40000&&!session.AudioClient3Available,"period0 preserves current shared initialization when interface3 absent");var ext=new FakeExtended();session=new Latency03OutputSession(Bank(),"authored",0,35,1);session.Initialize(ext,IntPtr.Zero);Need(ext.QueryCalls==1&&ext.LegacyCalls==1&&ext.NewCalls==0&&session.CurrentFormatSampleRate==48000,"baseline queries capabilities without switching initialization");ext=new FakeExtended();session=new Latency03OutputSession(Bank(),"authored",256,35,1);session.Initialize(ext,IntPtr.Zero);Need(ext.NewCalls==1&&ext.LegacyCalls==0&&ext.Selected==256,"explicit legal shared period uses supported API once");ext=new FakeExtended();session=new Latency03OutputSession(Bank(),"authored",100,35,1);Throws(()=>session.Initialize(ext,IntPtr.Zero),"unsupported period rejected without rounding/fallback");Need(ext.LegacyCalls+ext.NewCalls==0,"no fallback initializer");ext=new FakeExtended();ext.QueryResult=unchecked((int)0x80004005);session=new Latency03OutputSession(Bank(),"authored",0,35,1);Throws(()=>session.Initialize(ext,IntPtr.Zero),"failed capability query not hidden under baseline");
  session=new Latency03OutputSession(Bank(),"authored",0,35,1);using(var output=WasapiOutput.CreateSyntheticExperiment(new PcmRing(),session)){Need(!output.DeviceOpened&&!output.EverStarted&&!output.Ready.WaitOne(0),"factory construction cannot activate/query/start a real endpoint");}Need(session.OutputThreadJoined,"unstarted factory safely joins without endpoint access");Throws(()=>WasapiOutput.CreateSyntheticExperiment(new PcmRing(),session),"claimed session cannot create a second output even before endpoint access");
  var sealedBus=Bank();session=new Latency03OutputSession(sealedBus,"authored",0,35,1);sealedBus.Seal(new SyntheticPresentationClock(E,F,0));Throws(()=>WasapiOutput.CreateSyntheticExperiment(new PcmRing(),session),"authored clock cannot masquerade as endpoint mapping");session=new Latency03OutputSession(new PreparedTransientBus(1,2,.95),"authored",0,35,1);Throws(()=>WasapiOutput.CreateSyntheticExperiment(new PcmRing(),session),"missing original kernels fail before endpoint access");
 }
 static void AllocationIL(){var methods=new List<MethodInfo>();foreach(string n in new[]{"Submit","ObserveClock","Fail","WithinDeadline","RecordCallback","AllocatedBytes"})methods.Add(typeof(Latency03OutputSession).GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static));foreach(string n in new[]{"Observe","MapLatest","Reject","To100ns"})methods.Add(typeof(Latency03PresentationClock).GetMethod(n,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static));foreach(string n in new[]{"DiscardDescriptor","ClearClockPending","RetryClockPending"})methods.Add(typeof(PreparedTransientBus).GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance));
  var one=new Dictionary<byte,System.Reflection.Emit.OpCode>();var two=new Dictionary<byte,System.Reflection.Emit.OpCode>();foreach(var f in typeof(System.Reflection.Emit.OpCodes).GetFields(BindingFlags.Public|BindingFlags.Static)){var op=(System.Reflection.Emit.OpCode)f.GetValue(null);if(op.Size==1)one[(byte)op.Value]=op;else two[(byte)op.Value]=op;}foreach(var m in methods){Need(m!=null,"listed callback helper exists");byte[] il=m.GetMethodBody().GetILAsByteArray();for(int at=0;at<il.Length;){var op=il[at++]==0xfe?two[il[at++]]:one[il[at-1]];Need(op!=System.Reflection.Emit.OpCodes.Newobj&&op!=System.Reflection.Emit.OpCodes.Newarr&&op!=System.Reflection.Emit.OpCodes.Box,"callback application IL allocation-free: "+m.Name);switch(op.OperandType){case System.Reflection.Emit.OperandType.InlineNone:break;case System.Reflection.Emit.OperandType.ShortInlineBrTarget:case System.Reflection.Emit.OperandType.ShortInlineI:case System.Reflection.Emit.OperandType.ShortInlineVar:at++;break;case System.Reflection.Emit.OperandType.InlineVar:at+=2;break;case System.Reflection.Emit.OperandType.InlineI8:case System.Reflection.Emit.OperandType.InlineR:at+=8;break;case System.Reflection.Emit.OperandType.InlineSwitch:int n=BitConverter.ToInt32(il,at);at+=4+4*n;break;default:at+=4;break;}}}
 }
 public static int Main(){try{ClockTests();PendingTests();SubmissionTests();InitializeTests();AllocationIL();Console.WriteLine(new JavaScriptSerializer().Serialize(new{passed=true,checks,endpointOpened=false,gameLaunched=false,scope="Managed fake CoreAudio clients/render buffers plus deterministic observed-clock fixtures; real COM/device behavior remains unverified"}));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
